Given an array prices[] of non-negative integers, representing the prices of the stocks on different days, return the maximum profit possible by buying and selling the stocks on different days when at most one transaction is allowed. Here one transaction means 1 buy + 1 Sell. If it is not possible to make a profit then return 0.Note: Stock must be bought before being sold.Examples:Input: prices[] = [7, 10, 1, 3, 6, 9, 2]Output: 8Explanation: Buy for price 1 and sell for price 9. Input: prices[] = [7, 6, 4, 3, 1]Output: 0Explanation: Since the array is sorted in decreasing order, 0 profit can be made without making any transaction.Input: prices[] = [1, 3, 6, 9, 11]Output: 10Explanation: Since the array is sorted in increasing order, we can make maximum profit by buying at price[0] and selling at price[n-1]Try It YourselfTable of Content[Naive Approach] By exploring all possible pairs - O(n^2) Time and O(1) Space[Expected Approach] One Traversal Solution - O(n) Time and O(1) Space[Naive Approach] By exploring all possible pairs - O(n^2) Time and O(1) SpaceThe idea is to use two nested loops to explore all the possible ways to buy and sell stock. The outer loop decides the day to buy the stock and the inner loop decides the day to sell the stock. The maximum difference between the selling price and buying price between every pair of days will be our answer. 
            C++

    #include <iostream>
#include <vector>
using namespace std;

int maxProfit(vector<int> &prices) {  
    int n = prices.size();
    int res = 0;

    // Explore all possible ways to buy and sell stock
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
			res = max(res, prices[j] - prices[i]);
        }
    }
    return res;
}

int main() {
    vector<int> prices = {7, 10, 1, 3, 6, 9, 2};
    cout << maxProfit(prices) << endl;
    return 0;
}


            C

    #include <stdio.h>

int maxProfit(int prices[], int n) {
    int res = 0;

    // Explore all possible ways to buy and sell stock
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            if (prices[j] - prices[i] > res) {
                res = prices[j] - prices[i];
            }
        }
    }
    return res;
}

int main() {
    int prices[] = {7, 10, 1, 3, 6, 9, 2};
    int n = sizeof(prices) / sizeof(prices[0]);
    printf("%d\n", maxProfit(prices, n));
    return 0;
}


